from pathlib import Path


data_dir = Path(__file__).parent / "data"
data_dir.mkdir(exist_ok=True)

for run in range(1, 4):
    (data_dir / f"run_{run:02d}.csv").write_text(
        "# Generated by generate_dataset.py\n"
        "# Example measurement data\n"
        f"# run: {run}\n"
        f'# sample: "sample-{run}"\n'
        "time,signal\n"
        f"0,{run}\n"
        f"1,{run * 2}\n"
        f"2,{run * 3}\n"
        f"3,{run * 4}\n"
    )
